}

if (currVal.rawValue !== null && this.rawValue !== currVal.rawValue)//if prior selection exists, and new selection is different from prior selection
{	
    Value_1d_pA.rawValue = null;
    Value_1d_pB.rawValue = null;
    Value_1e_pA.rawValue = null;
    Value_1e_pB.rawValue = null;

    var newValue = this.rawValue;//capture the new value before resetting the form
    this.rawValue = newValue; //apply the new value after resetting the form
    currVal.rawValue = this.rawValue; //store new value in hidden field for comparison if this field is changed again

    if (this.rawValue == "2") {
        Value_1d_pB.rawValue = 0;
        Value_1d_pB.access = "protected";
        Value_1e_pB.rawValue = 0;
        Value_1e_pB.access = "protected";
    } else {
        Value_1d_pB.access = "open";
        Value_1e_pB.access = "open";
    }

}

else //if no prior selection exists, and making a selection for the first time
{ 
    currVal.rawValue = this.rawValue;
