    if (Page_3.Value_6g_checkbox.rawValue == 1) {
        var grossWeeklyIncome = (Page_1.Value_2a_pA.rawValue +
                                 Page_1.Value_2c_adjustInc_pA.rawValue);
    } else {
        var grossWeeklyIncome = (Page_1.Value_2a_pA.rawValue +
