if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	//Note: income cannot exceed 7692 due to constraints on 3d
	var income = Value_3d.rawValue;

	var support = 15;
	if (0 <= income && income <= 301) {
		support = 15;
	} else if (302 <= income && income <= 391) {
		support = 15 + Math.round(0.20*(income - 301));
	} else if (392 <= income && income <= 1000) {
		support = Math.round(0.22*income);
	} else if (1001 <= income && income <= 1600) {
		support = 220 + Math.round(0.21*(income - 1000));
	} else if (1601 <= income && income <= 2400) {
		support = 346 + Math.round(0.18*(income - 1600));
	} else if (2401 <= income && income <= 3500) {
		support = 490 + Math.round(0.14*(income - 2400));
	} else if (3501 <= income && income <= 5000) {
		support = 644 + Math.round(0.11*(income - 3500));
	} else if (5001 <= income && income <= 8654) {
		support = 809 + Math.round(0.10*(income - 5000));
	}
	this.rawValue = support;
} else {
	this.rawValue = null;
}

