	if (Page_1.RadioButtonList.rawValue == "2") {
		this.rawValue = null;
	}
	else {
		// If 3a = 0, enter 100%
		if (Page_2.Value_3a_pA.rawValue == 0){
			this.rawValue = 1;
		} else {
		// 6c Ã· 3a					
			this.rawValue =(Page_3.Value_6c_pA.rawValue / Page_2.Value_3a_pA.rawValue).toFixed(2);
		}
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Page_1.RadioButtonList.rawValue == "2") {
		this.rawValue = null;
	}
	else {
		// If 3a = 0, enter 100%
		if (Page_2.Value_3a_pB.rawValue == 0){
			this.rawValue = 1;
		} else {
		// 6c Ã· 3a					
			this.rawValue =(Page_3.Value_6c_pB.rawValue / Page_2.Value_3a_pB.rawValue).toFixed(2);
		}
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {

    // If 6d is NA or 6d â¥ 10%, enter 6c for each parent
    if (Page_1.RadioButtonList.rawValue == "2" || Value_6d_pA.rawValue >= .10) {
  		this.rawValue = Page_3.Value_6c_pA.rawValue;
    } else {
    /*// If 6d is < 10%, enter 6c or ((6d + 10%) x 3a) for 
    // each parent, whichever is less, */

		var adjustedShareAmount = (Value_6d_pA.rawValue + 0.10) * Page_2.Value_3a_pB.rawValue;

		var computedShareAmount = Math.min(Page_3.Value_6c_pA.rawValue, adjustedShareAmount);        
        // but not less than an amount from the shaded
        // area of the Guidelines Chart
        var income = Page_2.Value_3a_pB.rawValue;
        var support = 15;
        if (0 <= income && income <= 301) {
            support = 15;
        } else if (302 <= income && income <= 391) {
            support = 15 + Math.round(0.20*(income - 301));
        }

        this.rawValue = Math.max(computedShareAmount, support);
    }

} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {

    // If 6d is NA or 6d â¥ 10%, enter 6c for each parent
    if (Page_1.RadioButtonList.rawValue == "2" || Value_6d_pB.rawValue >= .10 ) {
        this.rawValue = Page_3.Value_6c_pB.rawValue;
    } else {
    // If 6d is < 10%, enter 6c or ((6d + 10%) x 3a) for 
    // each parent, whichever is less,
        var adjustedShareAmount = (Value_6d_pB.rawValue + 0.10) * Page_2.Value_3a_pA.rawValue;
        var computedShareAmount = Math.min(Page_3.Value_6c_pB.rawValue, adjustedShareAmount);

        // but not less than an amount from the shaded
        // area of the Guidelines Chart
        var income = Page_2.Value_3a_pA.rawValue;
        var support = 15;
        if (0 <= income && income <= 301) {
            support = 15;
        } else if (302 <= income && income <= 391) {
            support = 15 + Math.round(0.20*(income - 301));
        }

        this.rawValue = Math.max(computedShareAmount, support);
    }

} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Page_1.RadioButtonList.rawValue == "2") {
		this.rawValue = "Recipient";
	}
	else {
		if (Value_6e_pA.rawValue > Value_6e_pB.rawValue) {
			this.rawValue = "Recipient";
		}
		else if (Value_6e_pA.rawValue < Value_6e_pB.rawValue) {
			this.rawValue = "Payor"; 
		} 
		else {
			this.rawValue = "Recipient";
		}
	} 
} else {
	this.rawValue = null;
}

