			this.rawValue = "Payor";
		}
		else if (Value_6e_pA.rawValue < Value_6e_pB.rawValue) {
			this.rawValue = "Recipient"; 
		} 
		else {
			this.rawValue = "Payor";
		}
	} 
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
    if((Page_1.RadioButtonList.rawValue !== "2") &&
       ((Value_6f_pA.rawValue == "Recipient" && Page_1.Value_2c_pA.rawValue > 0) ||
		(Value_6f_pB.rawValue == "Recipient" && Page_1.Value_2c_pB.rawValue > 0))){
				this.rawValue = 1;
		} else {
		this.rawValue = 0;
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Value_6f_pA.rawValue == "Recipient") {
		 this.rawValue = Math.max(Value_6e_pA.rawValue - Value_6e_pB.rawValue, 0);
	}
	else {
		this.rawValue = Math.max(Value_6e_pB.rawValue - Value_6e_pA.rawValue,0); 
