	// If Parent B 3a > $391, enter 5b
	if (Page_2.Value_3a_pB.rawValue > 391){
		this.rawValue = Page_2.Value_5b_pA.rawValue;
	} else {
	// If Parent B 3a â¤ $391, enter the amount from the 
	// shaded area of the Guidelines Chart for Parent B 3a
		var income = Page_2.Value_3a_pB.rawValue;

		var support = 15;
		if (0 <= income && income <= 301) {
			support = 15;
		} else if (302 <= income && income <= 391) {
