		if (Page_2.Value_3a_pA.rawValue > 391){
			this.rawValue = Page_2.Value_5b_pB.rawValue;
		} else {
		// If Parent A 3a â¤ $249, enter the amount from the 
		// shaded area of the Guidelines Chart for the other  parent's 3a
			var income = Page_2.Value_3a_pA.rawValue;

			var support = 15;
			if (0 <= income && income <= 301) {
				support = 15;
			} else if (302 <= income && income <= 391) {
