        Page_2.Value_2g_pA_c1, Page_2.Value_2g_pB_c1, Page_2.Value_2g_total_1);

    var child_2 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pA_c2, Page_2.Value_2g_pB_c2, Page_2.Value_2g_total_2);

    var child_3 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pA_c3, Page_2.Value_2g_pB_c3, Page_2.Value_2g_total_3);

    var child_4 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pA_c4, Page_2.Value_2g_pB_c4, Page_2.Value_2g_total_4);

    var child_5 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pA_c5, Page_2.Value_2g_pB_c5, Page_2.Value_2g_total_5);

    this.rawValue = child_1 + child_2 + child_3 + child_4 + child_5;
} else {
    this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
    var child_1 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pB_c1, Page_2.Value_2g_pA_c1, Page_2.Value_2g_total_1);

    var child_2 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pB_c2, Page_2.Value_2g_pA_c2, Page_2.Value_2g_total_2);

    var child_3 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pB_c3, Page_2.Value_2g_pA_c3, Page_2.Value_2g_total_3);

    var child_4 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pB_c4, Page_2.Value_2g_pA_c4, Page_2.Value_2g_total_4);

    var child_5 = CalcChildCare.calcChildCareCostForOnechild(
        Page_2.Value_2g_pB_c5, Page_2.Value_2g_pA_c5, Page_2.Value_2g_total_5);

    this.rawValue = child_1 + child_2 + child_3 + child_4 + child_5;
} else {
    this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	// For Parent A: Parent B 3c x Parent A 6a
	this.rawValue =  Math.round(Page_2.Value_3c_pB.rawValue * Value_6a_pA.rawValue);	
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	// For Parent B: Parent A 3c x Parent B 6a
	this.rawValue =  Math.round(Page_2.Value_3c_pA.rawValue * Value_6a_pB.rawValue);	
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	this.rawValue =  Math.round(Value_5c_pA.rawValue + Value_6b_pA.rawValue);	
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	this.rawValue =  Math.round(Value_5c_pB.rawValue + Value_6b_pB.rawValue);	
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	this.rawValue = Math.max(Page_2.Value_3b.rawValue - 8654, 0)
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	this.rawValue = Math.round(Value_8a.rawValue * Page_2.Value_3c_pA
.rawValue);
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	this.rawValue = Math.round(Value_8a.rawValue * Page_2.Value_3c_pB.rawValue);
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Page_1.RadioButtonList.rawValue == "2") {
		// Get recipient 3a
		if (Page_3.Value_6f_pA.rawValue == "Recipient") {
			var recipient_3a = Page_2.Value_3a_pA.rawValue;  
		} else {
			var recipient_3a = Page_2.Value_3a_pB.rawValue;  
		}

		if ( recipient_3a == 0) {
			this.rawValue = 1;
		} else{
			// 6gÃ· 3a					
			this.rawValue =(Page_3.Value_6g.rawValue / recipient_3a).toFixed(2);
		}		
	} 
	else {
		this.rawValue = null; 		
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Value_7a.rawValue == null || Value_7a.rawValue >= 0.10) {
		this.rawValue = Page_3.Value_6g.rawValue;
	} else if (Value_7a.rawValue < 0.10) {
		// Get recipient and payor values
		if (Page_3.Value_6f_pA.rawValue == "Recipient") {
			var recipient_6e = Page_3.Value_6e_pA.rawValue;
			var income = Page_2.Value_3a_pB.rawValue;
			var payor_3a = Page_2.Value_3a_pB.rawValue;

		} else {
			var recipient_6e = Page_3.Value_6e_pB.rawValue;
			var income = Page_2.Value_3a_pA.rawValue;
			var payor_3a = Page_2.Value_3a_pA.rawValue;
		}

		//If 7a is < 10%, enter 6e, 6g, or ((7a + 10%) x Payor 3a)
		// whichever is less,
		var adjustedShareAmount = (Value_7a.rawValue + 0.10) * payor_3a;
		var computedShareAmount = Math.min(recipient_6e, Page_3.Value_6g.rawValue, adjustedShareAmount);

		// but not less than an amount from the shaded
		// area of the Guidelines Chart

		var support = 15;
		if (0 <= income && income <= 301) {
			support = 15;
		} else if (302 <= income && income <= 391) {
			support = 15 + Math.round(0.20*(income - 301));
		}
		this.rawValue = Math.max(computedShareAmount, support);
	} 
} else {
	this.rawValue = null;
}

var pA_role = null;

if (Page_1.RadioButtonList.rawValue == "2") {
		pA_role = "Recipient";
} else {
		if (Page_3.Value_6e_pA.rawValue > Page_3.Value_6e_pB.rawValue) {
			pA_role = "Recipient";
		}
		else if (Page_3.Value_6e_pA.rawValue < Page_3.Value_6e_pB.rawValue) {
			pA_role = "Payor"; 
		} 
		else {
			pA_role = "Recipient";
		}
} 


if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Page_1.SS_parent.rawValue === "A" && 
		Page_1.Value_2b_pB.rawValue > 0 && 
		pA_role == "Payor"){

		this.rawValue = Page_1.Value_2b_pB.rawValue;
	} else if (Page_1.SS_parent.rawValue === "B" &&
				Page_1.Value_2b_pA.rawValue > 0 &&
				pA_role == "Recipient"){
		this.rawValue = Page_1.Value_2b_pA.rawValue;
	} else{
		this.rawValue = 0;
	}
} else{
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Value_7b.rawValue > Value_7c.rawValue) {
		this.rawValue = Math.round(Value_7b.rawValue - Value_7c.rawValue);
	} else {
		this.rawValue = 0;
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	// Get payor 3a
	if (Page_3.Value_6f_pA.rawValue == "Payor") {
		var payor_3a = Page_2.Value_3a_pA.rawValue;  
	} else {
		var payor_3a = Page_2.Value_3a_pB.rawValue;  
	}

	if ( payor_3a == 0) {
		this.rawValue = 1;
	} else{
		// 7d Ã· 3a					
		this.rawValue =(Value_7d.rawValue / payor_3a).toFixed(2);
	}	

} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Value_7e.rawValue >= .40){
		this.rawValue = 1;
	} else {
		this.rawValue = null;
	}
} else {
	this.rawValue = null;
}

if (CheckIfInputsPopulated.checkIfInputsPopulated()) {
	if (Page_1.RadioButtonList.rawValue == "2") {
			this.presence = "hidden"; 
		} 
	else {
			this.presence = "visible";
			this.rawValue = "N/A"; 		
	}
}
else {
	this.presence = "hidden"; 
}

variables.script:
function checkIfChildrenInputsPopulated() {
	return (Page_1.Value_1a.rawValue != null &&
			Page_1.RadioButtonList.rawValue != null &&
			Page_1.Value_1d_pA.rawValue != null &&
			Page_1.Value_1d_pB.rawValue != null &&
			Page_1.Value_1e_pA.rawValue != null &&
			Page_1.Value_1e_pB.rawValue != null);
}

// Final trigger check
function checkIfFinalRequiredInputPopulated() {
    return (Page_1.Value_2a_pA.rawValue != null ||
            Page_1.Value_2a_pB.rawValue != null);
}

// Helpers (shared)
function isEmpty(v) {
    return (v === null || v === ""); // 0 is valid for numeric
}
function setBoxColor(node, makeRed) {
    var rgb = makeRed ? "255,80,61" : "255,255,255";
    try { node.ui.textEdit.border.fill.color.value = rgb; return; } catch(e) {}
    try { node.ui.numericEdit.border.fill.color.value = rgb; return; } catch(e) {}
    try { node.border.fill.color.value = rgb; } catch(_) {}
}

// 1a
function validateInput1a() {
    var empty = isEmpty(Page_1.Value_1a.rawValue);
    setBoxColor(Page_1.Value_1a, empty);

    if (empty) {
        Page_1.ErrorValue1a.rawValue = "Enter the number of children";
        Page_1.ErrorValue1a.presence = "visible";
        return false;
    } else {
        Page_1.ErrorValue1a.rawValue = "";
        Page_1.ErrorValue1a.presence = "hidden";
        return true;
    }
}

// 1b (radio list)
function validateInput1b() {

    var empty = (Page_1.RadioButtonList.rawValue != "1" && Page_1.RadioButtonList.rawValue != "2" && Page_1.RadioButtonList.rawValue != "3")

    if (empty) {
        Page_1.ErrorValue1b.rawValue = "Select a box";
        Page_1.ErrorValue1b.presence = "visible";
        return false;
    } else {
        Page_1.ErrorValue1b.rawValue = "";
        Page_1.ErrorValue1b.presence = "hidden";
        return true;
    }
}

// 1c pA / pB
function validateInput1c_pA() {
    var empty = isEmpty(Page_1.Value_1c_pA.rawValue);
    setBoxColor(Page_1.Value_1c_pA, empty);

    if (empty) {
        Page_1.ErrorParentName_A.rawValue = "Enter Parent A's Name";
        Page_1.ErrorParentName_A.presence = "visible";
        return false;
    } else {
        Page_1.ErrorParentName_A.rawValue = "";
        Page_1.ErrorParentName_A.presence = "hidden";
        return true;
    }
}
function validateInput1c_pB() {
    var empty = isEmpty(Page_1.Value_1c_pB.rawValue);
    setBoxColor(Page_1.Value_1c_pB, empty);

    if (empty) {
        Page_1.ErrorParentName_B.rawValue = "Enter Parent B's Name";
        Page_1.ErrorParentName_B.presence = "visible";
        return false;
    } else {
        Page_1.ErrorParentName_B.rawValue = "";
        Page_1.ErrorParentName_B.presence = "hidden";
        return true;
    }
}

// 1d/1e per-field validators (numeric boxes)
function validate_1d_pA() {
    var empty = isEmpty(Page_1.Value_1d_pA.rawValue);
    setBoxColor(Page_1.Value_1d_pA, empty);
    return !empty;
}
function validate_1e_pA() {
    var empty = isEmpty(Page_1.Value_1e_pA.rawValue);
    setBoxColor(Page_1.Value_1e_pA, empty);
    return !empty;
}
function validate_1d_pB() {
    var empty = isEmpty(Page_1.Value_1d_pB.rawValue);
    setBoxColor(Page_1.Value_1d_pB, empty);
    return !empty;
}
function validate_1e_pB() {
    var empty = isEmpty(Page_1.Value_1e_pB.rawValue);
    setBoxColor(Page_1.Value_1e_pB, empty);
    return !empty;
}

function validateInput1d_e() {
    var ok = true;
    if (!validate_1d_pA()) ok = false;
    if (!validate_1e_pA()) ok = false;
    if (!validate_1d_pB()) ok = false;
    if (!validate_1e_pB()) ok = false;

    if (!ok) {
        Page_1.ErrorValue1de.rawValue = "Enter the number of children under and over the age of 18";
        Page_1.ErrorValue1de.presence = "visible";
        return false;
    } else {
        Page_1.ErrorValue1de.rawValue = "";
        Page_1.ErrorValue1de.presence = "hidden";
        return true;
    }
}

// 1f validation (runs only after 1d/e group passes)
function validateInput1f() {
    // Ensure 1d/1e are valid first
    if (!validateInput1d_e()) {
        return false;
    }

    // Gate condition from your snippet
    var childrenGate = CheckIfChildrenInputsPopulated.checkIfChildrenInputsPopulated();
    var v1fA = Number(Page_1.Value_1f_pA.rawValue);
    var v1fB = Number(Page_1.Value_1f_pB.rawValue);
    var v1a  = Number(Page_1.Value_1a.rawValue);
    var rb   = Page_1.RadioButtonList.rawValue;

    // Only apply this validation when parent A's 1f > 0 AND children inputs are populated
    if (!(v1fA > 0 && childrenGate)) {
        // Do not show 1f error if the gate isnât met; leave any prior state alone.
        return true;
    }

    // Helper to color A/B boxes
    function color1f(aRed, bRed) {
        setBoxColor(Page_1.Value_1f_pA, !!aRed);
        setBoxColor(Page_1.Value_1f_pB, !!bRed);
    }

    // Default: assume valid; clear error at the end if still valid
    var valid = true;

    switch (rb) {
        case "1":
            // Box 1: Parent A's 1f must equal 1a
            if (v1fA !== v1a) {
                Page_1.ErrorMessageBox.rawValue   = "You have selected Box 1 in line 1b. The number of children\nin line 1f for both parents must equal the value in line 1a.";
                Page_1.ErrorMessageBox.presence   = "visible";
                color1f(true, false); // highlight A
                valid = false;
            } else {
                color1f(false, false);
            }
            break;

        case "2":
            // Box 2: Parent A's 1f must equal 1a
            if (v1fA !== v1a) {
                Page_1.ErrorMessageBox.rawValue   = "You have selected Box 2 in line 1b. The number of children\nin line 1f for Parent A must equal the value in line 1a.";
                Page_1.ErrorMessageBox.presence   = "visible";
                color1f(true, false); // highlight A
                valid = false;
            } else {
                color1f(false, false);
            }
            break;

        case "3":
            // Box 3: sum(A+B) must equal 1a, 1a must be > 1, and neither A nor B can be 0
            if (v1a === 1) {
                Page_1.ErrorMessageBox.rawValue = "You have selected Box 3 in line 1b. Box 3 requires more than\none child covered by the order in 1a.";
                Page_1.ErrorMessageBox.presence = "visible";
                color1f(true, true); // highlight both (rule involves both)
                valid = false;
            } else if (v1a !== 1 && (v1fA === 0 || v1fB === 0)) {
                Page_1.ErrorMessageBox.rawValue = "You have selected Box 3 in line 1b. Each parent must provide \na primary residence for at least one child.";
                Page_1.ErrorMessageBox.presence = "visible";
                color1f(v1fA === 0, v1fB === 0); // highlight whichever is 0
                valid = false;
            } else if ((v1fA + v1fB) !== v1a) {
                Page_1.ErrorMessageBox.rawValue = "You have selected Box 3 in line 1b. The number of children\nin line 1f for both parents must sum to the value in line 1a.";
                Page_1.ErrorMessageBox.presence = "visible";
                color1f(true, true); // mismatch involves both
                valid = false;
            } else {
                color1f(false, false);
            }
            break;

        default:
            // No radio choice or unexpected value â treat as no 1f constraint here
            color1f(false, false);
            break;
    }

    if (!valid) {
        return false;
    } else {
        Page_1.ErrorMessageBox.rawValue = "";
        Page_1.ErrorMessageBox.presence = "hidden";
        color1f(false, false);
        return true;
    }
}


//2a_ss 
function validateInput2a_SS_benefit() {
    var v = Page_1.SS_benefit.rawValue;
    var missing = (v !== "Yes" && v !== "No");

    if (missing) {
        Page_1.ErrorMessageBox_2a.rawValue = "Enter whether a child receives a Social Security dependency benefit";
        Page_1.ErrorMessageBox_2a.presence = "visible";
        return false;
    } else {
        Page_1.ErrorMessageBox_2a.rawValue = "";
        Page_1.ErrorMessageBox_2a.presence = "hidden";
        return true;
    }
}

// 2b dependency: if SS_benefit == "Yes", require SS_parent AND at least one of Value_2b_pA / Value_2b_pB
function validateInput2a_SS_rules() {
    var vBenefit = Page_1.SS_benefit.rawValue;   // "Yes" / "No" / empty
    var vParent  = Page_1.SS_parent.rawValue;    // expected "A" or "B" 

    // Parent requirement
    var parentMissing = (vParent !== "A" && vParent !== "B");

    // Amount requirement
    var aEmpty = isEmpty(Page_1.Value_2b_pA.rawValue);
    var bEmpty = isEmpty(Page_1.Value_2b_pB.rawValue);
    var amountsMissing = (aEmpty && bEmpty);

    if (vBenefit === "Yes") {
        // Show or hide parent message
        if (parentMissing) {
            Page_1.ErrorMessageBox_2a_parent.rawValue = "Select the parent who receives the Social Security dependency benefit.";
            Page_1.ErrorMessageBox_2a_parent.presence = "visible";
        } else {
            Page_1.ErrorMessageBox_2a_parent.rawValue = "";
            Page_1.ErrorMessageBox_2a_parent.presence = "hidden";
        }

        // Show or hide amount message
        if (amountsMissing) {
            Page_1.ErrorMessageBox_2b.rawValue = "Enter the amount of Social Security dependency benefit sent to each parent.";
            Page_1.ErrorMessageBox_2b.presence = "visible";
            try { setBoxColor(Page_1.Value_2b_pA, true ); } catch (_) {}
       			try { setBoxColor(Page_1.Value_2b_pB, true ); } catch (_) {}
        } else {
            Page_1.ErrorMessageBox_2b.rawValue = "";
            Page_1.ErrorMessageBox_2b.presence = "hidden";
            try { setBoxColor(Page_1.Value_2b_pA, false ); } catch (_) {}
       			try { setBoxColor(Page_1.Value_2b_pB, false ); } catch (_) {}
        }
        // Overall validity
        return !(parentMissing || amountsMissing);
    } else {
        // Not "Yes": clear both messages and colors
        Page_1.ErrorMessageBox_2a_parent.rawValue = "";
        Page_1.ErrorMessageBox_2a_parent.presence = "hidden";
        Page_1.ErrorMessageBox_2b.rawValue = "";
        Page_1.ErrorMessageBox_2b.presence = "hidden";

        try { setBoxColor(Page_1.Value_2b_pA, false); } catch (_) {}
        try { setBoxColor(Page_1.Value_2b_pB, false); } catch (_) {}

        return true;
    }
}

function validateAllInputs() {
    var ok = true;

    if (!validateInput1a()) ok = false;
    if (!validateInput1b()) ok = false;
    if (!validateInput1c_pA()) ok = false;
    if (!validateInput1c_pB()) ok = false;

    var okDe = validateInput1d_e();
    if (!okDe) ok = false;

    if (okDe && !validateInput1f()) ok = false;

    if (!validateInput2a_SS_benefit()) ok = false;
    if (!validateInput2a_SS_rules()) ok = false;

    return ok;
}


function checkInput1fMathOnly() {
    var v1fA = Number(Page_1.Value_1f_pA.rawValue);
    var v1fB = Number(Page_1.Value_1f_pB.rawValue);
    var v1a  = Number(Page_1.Value_1a.rawValue);
    var rb   = Page_1.RadioButtonList.rawValue;

    switch (rb) {
        case "1":
            // Box 1: Parent A's 1f must equal 1a
            return v1fA === v1a;

        case "2":
            // Box 2: Parent A's 1f must equal 1a
            return v1fA === v1a;

        case "3":
            // Box 3: sum(A+B) must equal 1a, 1a must be > 1, and neither A nor B can be 0
            if (v1a === 1) {
                return false;
            } else if (v1fA === 0 || v1fB === 0) {
                return false;
            } else if ((v1fA + v1fB) !== v1a) {
                return false;
            } else {
                return true;
            }

        default:
            // No radio choice or unexpected value â no math constraint
            return true;
    }
}


function checkInput2bMathOnly(){
  const vBenefit = Page_1.SS_benefit.rawValue;   // "Yes" / "No" / empty
  const vParent  = Page_1.SS_parent.rawValue;    // "A" or "B"
  const aEmpty   = isEmpty(Page_1.Value_2b_pA.rawValue);
  const bEmpty   = isEmpty(Page_1.Value_2b_pB.rawValue);

  // Valid iff: not Yes OR (parent chosen AND at least one amount provided)
  return (vBenefit !== "Yes") ||
         ((vParent === "A" || vParent === "B") && !(aEmpty && bEmpty));
}

function checkIfInputsPopulated() {
	return (Page_1.Value_1a.rawValue != null &&

	       (Page_1.RadioButtonList.rawValue == "1" || Page_1.RadioButtonList.rawValue == "2" || Page_1.RadioButtonList.rawValue == "3")  &&

			Page_1.Value_1c_pA.rawValue != null &&
			Page_1.Value_1c_pB.rawValue != null &&
			Page_1.Value_1d_pA.rawValue != null &&
			Page_1.Value_1d_pB.rawValue != null &&
			Page_1.Value_1e_pA.rawValue != null &&
			Page_1.Value_1e_pB.rawValue != null && 
			Page_1.Value_2a_pA.rawValue != null &&
			Page_1.Value_2a_pB.rawValue != null &&
			(Page_1.SS_benefit.rawValue === "Yes" ||
			Page_1.SS_benefit.rawValue === "No") &&
			checkInput1fMathOnly() &&
			checkInput2bMathOnly()
			);
}

function checkIf2bPopulated() {
	return (Page_1.Value_2b_pA.rawValue != null ||
			Page_1.Value_2b_pB.rawValue != null);
}

function checkIf2cPopulated() {
	return (Page_1.Value_2c_pA.rawValue != null ||
			Page_1.Value_2c_pB.rawValue != null);
}

