function calcChildCareCostForOnechild(value_2g_pA, value_2g_pB, value_2g_total) {
    var child_1 = 0;

    if (value_2g_total.rawValue <= 430) {
       child_1 = value_2g_pA.rawValue;
    } else if (value_2g_total.rawValue > 430) {
        child_1 = Math.round(value_2g_pA.rawValue * (430/value_2g_total.rawValue));
    } else {
        child_1 = 0;
    }

	return child_1;
}
